use std::time::Duration;

pub fn parse_duration(s: &str) -> Duration {
    let n: u64 = s.trim_end_matches('s').parse().unwrap();
    Duration::from_secs(n)
}

fn main() {
    println!("{:?}", parse_duration("5s"));
    println!("{:?}", parse_duration("100ms"));
    println!("{:?}", parse_duration("2m"));
}
